{
  "name": "campusnav-mobile",
  "version": "0.1.0",
  "private": true,
  "main": "expo/AppEntry",
  "scripts": {
    "start": "expo start",
    "android": "expo start --android",
    "ios": "expo start --ios",
    "typecheck": "tsc --noEmit -p tsconfig.json",
    "test": "vitest run"
  },
  "dependencies": {
    "expo": "^53.0.0",
    "react": "^19.0.0",
    "react-native": "^0.79.0"
  },
  "devDependencies": {
    "@types/node": "^25.2.3",
    "@types/react": "^19.2.14",
    "typescript": "^5.9.3",
    "vitest": "^4.0.18"
  }
}

import { defineConfig } from 'vitest/config';

export default defineConfig({
  test: {
    environment: 'node',
    globals: true,
    include: ['**/*.test.ts'],
    clearMocks: true,
    restoreMocks: true,
  },
});

import { useCallback, useEffect, useState } from 'react';
import { ActivityIndicator, Pressable, StyleSheet, Text, View } from 'react-native';

import {
  IDLE_BOOTSTRAP_STATE,
  type BootstrapState,
  runAppBootstrap,
} from './bootstrap/appBootstrap';

function nextAttemptFromState(state: BootstrapState): number {
  if (state.phase === 'idle') {
    return 1;
  }

  return state.attempt + 1;
}

function phaseMessage(state: BootstrapState): string {
  switch (state.phase) {
    case 'idle':
      return 'Preparing startup checks.';
    case 'loading':
      return 'Starting CampusNav runtime.';
    case 'ready':
      return 'CampusNav is ready. No sign-in required.';
    case 'error':
      return state.message;
  }
}

export default function App() {
  const [bootstrapState, setBootstrapState] = useState<BootstrapState>(IDLE_BOOTSTRAP_STATE);

  const executeBootstrap = useCallback(async (attempt: number) => {
    const result = await runAppBootstrap({ attempt });

    for (const transition of result.transitions) {
      if (transition.phase === 'ready') {
        console.info('[mobile-bootstrap]', {
          phase: transition.phase,
          attempt: transition.attempt,
          endpoint: transition.apiBaseUrl,
        });
        continue;
      }

      if (transition.phase === 'error') {
        console.warn('[mobile-bootstrap]', {
          phase: transition.phase,
          reason: transition.reason,
          attempt: transition.attempt,
          failedPhase: transition.failedPhase,
        });
        continue;
      }

      if (transition.phase === 'loading') {
        console.info('[mobile-bootstrap]', {
          phase: transition.phase,
          attempt: transition.attempt,
        });
      }
    }

    setBootstrapState(result.state);
  }, []);

  useEffect(() => {
    void executeBootstrap(1);
  }, [executeBootstrap]);

  const onRetryPress = () => {
    void executeBootstrap(nextAttemptFromState(bootstrapState));
  };

  return (
    <View style={styles.container}>
      <Text style={styles.title}>CampusNav</Text>
      <Text style={styles.subtitle}>Visitor bootstrap shell</Text>

      <Text style={styles.statusLabel}>Bootstrap phase: {bootstrapState.phase}</Text>
      <Text style={styles.statusMessage}>{phaseMessage(bootstrapState)}</Text>

      {bootstrapState.phase === 'loading' ? <ActivityIndicator size="small" color="#38bdf8" /> : null}

      {bootstrapState.phase === 'ready' ? (
        <Text style={styles.readyText}>API endpoint: {bootstrapState.apiBaseUrl}</Text>
      ) : null}

      {bootstrapState.phase === 'error' ? (
        <View style={styles.errorContainer}>
          <Text style={styles.errorReason}>Reason: {bootstrapState.reason}</Text>
          <Pressable onPress={onRetryPress} style={styles.retryButton}>
            <Text style={styles.retryButtonText}>Retry startup</Text>
          </Pressable>
        </View>
      ) : null}
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#020617',
    alignItems: 'center',
    justifyContent: 'center',
    paddingHorizontal: 24,
    gap: 10,
  },
  title: {
    color: '#f8fafc',
    fontSize: 28,
    fontWeight: '700',
  },
  subtitle: {
    color: '#cbd5e1',
    fontSize: 14,
    marginBottom: 12,
  },
  statusLabel: {
    color: '#e2e8f0',
    fontSize: 15,
    fontWeight: '600',
  },
  statusMessage: {
    color: '#94a3b8',
    textAlign: 'center',
    fontSize: 14,
    marginBottom: 10,
  },
  readyText: {
    color: '#38bdf8',
    fontSize: 13,
    textAlign: 'center',
  },
  errorContainer: {
    marginTop: 6,
    alignItems: 'center',
    gap: 8,
  },
  errorReason: {
    color: '#fda4af',
    fontSize: 13,
  },
  retryButton: {
    backgroundColor: '#0f172a',
    borderColor: '#475569',
    borderWidth: 1,
    borderRadius: 8,
    paddingHorizontal: 14,
    paddingVertical: 8,
  },
  retryButtonText: {
    color: '#f8fafc',
    fontSize: 13,
    fontWeight: '600',
  },
});

{
  "expo": {
    "name": "CampusNav",
    "slug": "campusnav-mobile",
    "scheme": "campusnav",
    "version": "0.1.0",
    "orientation": "portrait",
    "userInterfaceStyle": "automatic",
    "ios": {
      "supportsTablet": true,
      "bundleIdentifier": "com.campusnav.mobile"
    },
    "android": {
      "package": "com.campusnav.mobile"
    }
  }
}

module.exports = function (api) {
  api.cache(true);

  return {
    presets: ['babel-preset-expo'],
  };
};

import {
  STARTUP_TIMEOUT_MS,
  validateApiBaseUrl,
  runAppBootstrap,
} from './appBootstrap';

describe('runAppBootstrap', () => {
  it('transitions from loading to ready when EXPO_PUBLIC_API_BASE_URL is valid', async () => {
    const result = await runAppBootstrap({
      env: {
        EXPO_PUBLIC_API_BASE_URL: 'https://campusnav.example.com/',
      },
      toolingCheck: async () => ({ status: 'ok' }),
    });

    expect(result.transitions.map((state) => state.phase)).toEqual(['loading', 'ready']);
    expect(result.state.phase).toBe('ready');

    if (result.state.phase !== 'ready') {
      throw new Error('Expected ready bootstrap state.');
    }

    expect(result.state.apiBaseUrl).toBe('https://campusnav.example.com');
    expect(result.state.authRequired).toBe(false);
  });

  it('transitions to error when EXPO_PUBLIC_API_BASE_URL is missing', async () => {
    const result = await runAppBootstrap({
      env: {},
      toolingCheck: async () => ({ status: 'ok' }),
    });

    expect(result.transitions.map((state) => state.phase)).toEqual(['loading', 'error']);
    expect(result.state.phase).toBe('error');

    if (result.state.phase !== 'error') {
      throw new Error('Expected error bootstrap state.');
    }

    expect(result.state.reason).toBe('missing-api-base-url');
    expect(result.state.failedPhase).toBe('loading');
    expect(result.state.authRequired).toBe(false);
  });

  it('transitions to error when EXPO_PUBLIC_API_BASE_URL is malformed', async () => {
    const result = await runAppBootstrap({
      env: {
        EXPO_PUBLIC_API_BASE_URL: 'not-a-url',
      },
      toolingCheck: async () => ({ status: 'ok' }),
    });

    expect(result.state.phase).toBe('error');

    if (result.state.phase !== 'error') {
      throw new Error('Expected error bootstrap state.');
    }

    expect(result.state.reason).toBe('invalid-api-base-url');
    expect(result.state.authRequired).toBe(false);
  });

  it('transitions to error on startup timeout with bounded wait', async () => {
    const result = await runAppBootstrap({
      env: {
        EXPO_PUBLIC_API_BASE_URL: 'https://campusnav.example.com',
      },
      timeoutMs: 15,
      toolingCheck: () => new Promise((resolve) => setTimeout(() => resolve({ status: 'ok' }), 30)),
    });

    expect(result.state.phase).toBe('error');

    if (result.state.phase !== 'error') {
      throw new Error('Expected error bootstrap state.');
    }

    expect(result.state.reason).toBe('startup-timeout');
    expect(result.state.message).toContain('timed out');
  });

  it('transitions to error when startup tooling returns malformed config shape', async () => {
    const result = await runAppBootstrap({
      env: {
        EXPO_PUBLIC_API_BASE_URL: 'https://campusnav.example.com',
      },
      toolingCheck: async () => ({ ok: true }),
    });

    expect(result.state.phase).toBe('error');

    if (result.state.phase !== 'error') {
      throw new Error('Expected error bootstrap state.');
    }

    expect(result.state.reason).toBe('invalid-startup-config');
  });

  it('is idempotent across repeated invocation and never regresses to auth-required state', async () => {
    const env = {
      EXPO_PUBLIC_API_BASE_URL: 'https://campusnav.example.com',
    };

    const first = await runAppBootstrap({
      env,
      attempt: 1,
      toolingCheck: async () => ({ status: 'ok' }),
    });

    const second = await runAppBootstrap({
      env,
      attempt: 2,
      toolingCheck: async () => ({ status: 'ok' }),
    });

    expect(first.state.phase).toBe('ready');
    expect(second.state.phase).toBe('ready');

    if (first.state.phase !== 'ready' || second.state.phase !== 'ready') {
      throw new Error('Expected repeated bootstrap calls to be ready.');
    }

    expect(first.state.apiBaseUrl).toBe(second.state.apiBaseUrl);
    expect(first.state.authRequired).toBe(false);
    expect(second.state.authRequired).toBe(false);
    expect(second.state.attempt).toBeGreaterThan(first.state.attempt);
  });
});

describe('validateApiBaseUrl', () => {
  it('requires a URL with http/https protocol', () => {
    const ftpResult = validateApiBaseUrl('ftp://example.com/path');
    expect(ftpResult.ok).toBe(false);

    if (ftpResult.ok) {
      throw new Error('Expected invalid result for unsupported protocol.');
    }

    expect(ftpResult.reason).toBe('invalid-api-base-url');
  });

  it('keeps startup timeout constant explicit and bounded', () => {
    expect(STARTUP_TIMEOUT_MS).toBeGreaterThan(0);
    expect(STARTUP_TIMEOUT_MS).toBeLessThanOrEqual(5_000);
  });
});

export const STARTUP_TIMEOUT_MS = 3_000;

export type BootstrapPhase = 'idle' | 'loading' | 'ready' | 'error';

export type BootstrapErrorReason =
  | 'missing-api-base-url'
  | 'invalid-api-base-url'
  | 'startup-timeout'
  | 'startup-tooling-error'
  | 'invalid-startup-config';

export type BootstrapState =
  | {
      phase: 'idle';
      authRequired: false;
    }
  | {
      phase: 'loading';
      authRequired: false;
      attempt: number;
      startedAtMs: number;
    }
  | {
      phase: 'ready';
      authRequired: false;
      attempt: number;
      apiBaseUrl: string;
    }
  | {
      phase: 'error';
      authRequired: false;
      attempt: number;
      reason: BootstrapErrorReason;
      message: string;
      failedPhase: 'loading';
      recoverable: boolean;
    };

export interface BootstrapResult {
  state: BootstrapState;
  transitions: BootstrapState[];
}

export interface BootstrapOptions {
  env?: Record<string, string | undefined>;
  attempt?: number;
  timeoutMs?: number;
  now?: () => number;
  toolingCheck?: () => Promise<unknown>;
}

interface ValidUrlResult {
  ok: true;
  normalizedUrl: string;
}

interface InvalidUrlResult {
  ok: false;
  reason: Extract<BootstrapErrorReason, 'missing-api-base-url' | 'invalid-api-base-url'>;
  message: string;
}

const DEFAULT_IDLE_STATE: BootstrapState = {
  phase: 'idle',
  authRequired: false,
};

export const IDLE_BOOTSTRAP_STATE = DEFAULT_IDLE_STATE;

export function createLoadingState(attempt: number, now: () => number): BootstrapState {
  return {
    phase: 'loading',
    authRequired: false,
    attempt,
    startedAtMs: now(),
  };
}

export function validateApiBaseUrl(rawValue: string | undefined): ValidUrlResult | InvalidUrlResult {
  const value = rawValue?.trim();

  if (!value) {
    return {
      ok: false,
      reason: 'missing-api-base-url',
      message: 'EXPO_PUBLIC_API_BASE_URL is missing.',
    };
  }

  try {
    const parsed = new URL(value);

    if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
      return {
        ok: false,
        reason: 'invalid-api-base-url',
        message: 'EXPO_PUBLIC_API_BASE_URL must use http or https.',
      };
    }

    parsed.hash = '';

    return {
      ok: true,
      normalizedUrl: parsed.toString().replace(/\/$/, ''),
    };
  } catch {
    return {
      ok: false,
      reason: 'invalid-api-base-url',
      message: 'EXPO_PUBLIC_API_BASE_URL must be a valid absolute URL.',
    };
  }
}

function toBootstrapError(
  reason: BootstrapErrorReason,
  message: string,
  attempt: number,
  recoverable = true,
): BootstrapState {
  return {
    phase: 'error',
    authRequired: false,
    attempt,
    reason,
    message,
    failedPhase: 'loading',
    recoverable,
  };
}

function isValidStartupToolingResult(result: unknown): result is { status: 'ok' } {
  return !!result && typeof result === 'object' && (result as { status?: string }).status === 'ok';
}

async function defaultToolingCheck(): Promise<{ status: 'ok' }> {
  return { status: 'ok' };
}

async function runWithTimeout<T>(
  promise: Promise<T>,
  timeoutMs: number,
  message: string,
): Promise<T> {
  let timeoutHandle: ReturnType<typeof setTimeout> | undefined;

  const timeoutPromise = new Promise<T>((_, reject) => {
    timeoutHandle = setTimeout(() => {
      reject(new Error(message));
    }, timeoutMs);
  });

  try {
    return await Promise.race([promise, timeoutPromise]);
  } finally {
    if (timeoutHandle) {
      clearTimeout(timeoutHandle);
    }
  }
}

export async function runAppBootstrap(options: BootstrapOptions = {}): Promise<BootstrapResult> {
  const now = options.now ?? Date.now;
  const attempt = Math.max(1, options.attempt ?? 1);
  const timeoutMs = options.timeoutMs ?? STARTUP_TIMEOUT_MS;
  const toolingCheck = options.toolingCheck ?? defaultToolingCheck;
  const env = options.env ?? process.env;

  const loadingState = createLoadingState(attempt, now);
  const transitions: BootstrapState[] = [loadingState];

  try {
    const toolingResult = await runWithTimeout(
      toolingCheck(),
      timeoutMs,
      'Startup tooling check timed out.',
    );

    if (!isValidStartupToolingResult(toolingResult)) {
      const malformedConfigState = toBootstrapError(
        'invalid-startup-config',
        'Startup tooling returned an invalid configuration shape.',
        attempt,
        false,
      );
      transitions.push(malformedConfigState);
      return {
        state: malformedConfigState,
        transitions,
      };
    }
  } catch (error) {
    const reason: BootstrapErrorReason =
      error instanceof Error && error.message === 'Startup tooling check timed out.'
        ? 'startup-timeout'
        : 'startup-tooling-error';

    const toolingErrorState = toBootstrapError(
      reason,
      error instanceof Error ? error.message : 'Startup tooling check failed.',
      attempt,
      true,
    );
    transitions.push(toolingErrorState);

    return {
      state: toolingErrorState,
      transitions,
    };
  }

  const apiValidation = validateApiBaseUrl(env.EXPO_PUBLIC_API_BASE_URL);

  if (!apiValidation.ok) {
    const configErrorState = toBootstrapError(
      apiValidation.reason,
      apiValidation.message,
      attempt,
      false,
    );
    transitions.push(configErrorState);

    return {
      state: configErrorState,
      transitions,
    };
  }

  const readyState: BootstrapState = {
    phase: 'ready',
    authRequired: false,
    attempt,
    apiBaseUrl: apiValidation.normalizedUrl,
  };
  transitions.push(readyState);

  return {
    state: readyState,
    transitions,
  };
}

